<?php
if(PHP_SAPI!=='cli'){http_response_code(404);exit;}
require __DIR__.'/../global/connection.php';require_once __DIR__.'/qa-http-client.php';
if(!str_ends_with(DB,'_qa'))throw new RuntimeException('Use una base _qa.');
$http=new AppQaHttpClient(getenv('APPU_QA_URL')?:'http://127.0.0.1:8765',DB);$key='QA-GRH-'.bin2hex(random_bytes(4));$provider=$product=$order=$line=$receipt=null;$failed=false;
function receiptHttpAssert(bool $ok,string $message):void{if(!$ok)throw new RuntimeException($message);}
try{
 $user=(int)$pdo->query('SELECT id FROM tbl_user ORDER BY id LIMIT 1')->fetchColumn();$warehouse=(int)$pdo->query('SELECT id FROM tbl_warehouse WHERE active_status=1 ORDER BY id LIMIT 1')->fetchColumn();receiptHttpAssert($user>0&&$warehouse>0,'Faltan usuario o almacén QA.');
 $pdo->prepare("INSERT INTO tbl_provider(code,business_name,address,country,city,district,contact1_name,contact1_phone,contact2_name,contact2_phone,bank1_name,bank1_currency,bank1_account_number,bank1_account_holder,bank2_name,bank2_currency,bank2_account_number,bank2_account_holder)VALUES(?,?,'Dirección QA','Perú','Lima','Lima','','','','','','','','','','','','')")->execute([$key,'Proveedor HTTP recepción']);$provider=(int)$pdo->lastInsertId();
 $pdo->prepare("INSERT INTO tbl_product(code,brand,name,description,stock_quantity,unit_price,unit_value,active_status)VALUES(?,'QA','Artículo HTTP recepción','Temporal',0,10,'UND',1)")->execute([$key]);$product=(int)$pdo->lastInsertId();
 $pdo->prepare("INSERT INTO tbl_order(type,number,status,currency,issue_date,delivery_date,provider_id,provider_address,payment_days,account_number,quotation,requester,approver,created_by,observation,total_purchase,total_tax,total_net,exchange_rate_sale,exchange_rate_purchase)VALUES(1,?,'Aprobado','PEN',CURDATE(),CURDATE(),?,'Dirección documento',0,'','','','',?,'QA',100,18,118,0,0)")->execute([$key,$provider,$user]);$order=(int)$pdo->lastInsertId();
 $pdo->prepare("INSERT INTO tbl_order_detail(order_id,item_id,item_code,item_description,item_gloss,item_unit_value,item_unit_price,item_quantity,item_discount_rate,item_discounted_total)VALUES(?,?,?,?,?,'UND',10,10,0,100)")->execute([$order,$product,$key,'Artículo HTTP recepción','']);$line=(int)$pdo->lastInsertId();
 [$status,$eligible]=$http->request('/modules/compras/goods-receipts.php?action=eligible');receiptHttpAssert($status===200&&count(array_filter($eligible['bases'],fn($row)=>$row['base_type']==='ORDER'&&(int)$row['id']===$order))===1,'La orden aprobada no aparece como base elegible.');
 [$status,$base]=$http->request('/modules/compras/goods-receipts.php?base_type=ORDER&base_id='.$order);receiptHttpAssert($status===200&&(int)$base['details'][0]['pending_quantity']===10,'No cargó el saldo de la línea base.');
 $items=json_encode([['base_line_id'=>$line,'quantity'=>4,'lot_number'=>$key.'-L1','expiration_date'=>date('Y-m-d',strtotime('+180 days'))]]);
 [$status,$created]=$http->request('/modules/compras/goods-receipts.php',['action'=>'create','base_type'=>'ORDER','base_id'=>$order,'warehouse_id'=>$warehouse,'receipt_date'=>date('Y-m-d'),'supplier_delivery_reference'=>'GUÍA-'.$key,'items'=>$items]);receiptHttpAssert($status===201,'No creó la entrada: '.json_encode($created));$receipt=(int)($created['receipt_id']??0);receiptHttpAssert($receipt>0,'No devolvió el ID de entrada.');
 receiptHttpAssert($pdo->query("SELECT status FROM tbl_order WHERE id={$order}")->fetchColumn()==='Parcial','La recepción parcial no actualizó la orden.');$stock=$pdo->prepare('SELECT quantity,inventory_value FROM tbl_warehouse_stock WHERE warehouse_id=? AND product_id=?');$stock->execute([$warehouse,$product]);$stockRow=$stock->fetch();receiptHttpAssert((float)$stockRow['quantity']===4.0&&(float)$stockRow['inventory_value']===40.0,'La entrada no contabilizó cantidad y valor.');
 [$status,$saved]=$http->request('/modules/compras/goods-receipts.php?action=receipt&receipt_id='.$receipt);receiptHttpAssert($status===200&&$saved['receipt']['base_document_type']==='ORDER'&&(int)$saved['details'][0]['quantity']===4,'La consulta no reconstruye la entrada guardada.');
 [$status,$error]=$http->request('/modules/compras/goods-receipts.php',['action'=>'create','base_type'=>'ORDER','base_id'=>$order,'warehouse_id'=>$warehouse,'receipt_date'=>date('Y-m-d'),'items'=>json_encode([['base_line_id'=>$line,'quantity'=>7]])]);receiptHttpAssert($status===422&&str_contains((string)($error['message']??''),'supera'),'Se permitió recibir más que el saldo pendiente.');
 [$status,$cancelled]=$http->request('/modules/compras/goods-receipts.php',['action'=>'cancel','receipt_id'=>$receipt,'reason'=>'Reversión integral HTTP QA']);receiptHttpAssert($status===200,'No anuló la entrada: '.json_encode($cancelled));receiptHttpAssert($pdo->query("SELECT status FROM tbl_order WHERE id={$order}")->fetchColumn()==='Aprobado','La anulación no reabrió la orden.');$stock->execute([$warehouse,$product]);$stockRow=$stock->fetch();receiptHttpAssert((float)$stockRow['quantity']===0.0&&(float)$stockRow['inventory_value']===0.0,'La anulación no revirtió cantidad y valor.');
 $flow=$pdo->prepare("SELECT COUNT(*) FROM tbl_document_line_application WHERE source_type='order' AND source_id=? AND target_type='goods_receipt' AND target_id=? AND status='REVERSED'");$flow->execute([$order,$receipt]);receiptHttpAssert((int)$flow->fetchColumn()===1,'La anulación no revirtió la trazabilidad de línea.');echo "PASS HTTP purchase order goods receipt partial stock value overreceipt and cancellation\n";
}catch(Throwable $e){fwrite(STDERR,'FAIL goods receipt HTTP: '.$e->getMessage().PHP_EOL);$failed=true;}
finally{
 if($pdo->inTransaction())$pdo->rollBack();$pdo->beginTransaction();if($receipt){$pdo->prepare("DELETE FROM tbl_document_status_history WHERE document_type='goods_receipt' AND document_id=?")->execute([$receipt]);$pdo->prepare("DELETE FROM tbl_document_flow WHERE target_type='goods_receipt' AND target_id=?")->execute([$receipt]);$pdo->prepare("DELETE FROM tbl_document_line_application WHERE target_type='goods_receipt' AND target_id=?")->execute([$receipt]);$pdo->prepare("DELETE FROM tbl_warehouse_movement WHERE source_type='goods_receipt' AND source_id=?")->execute([$receipt]);$pdo->prepare('DELETE FROM tbl_goods_receipt_detail WHERE goods_receipt_id=?')->execute([$receipt]);$pdo->prepare('DELETE FROM tbl_goods_receipt WHERE id=?')->execute([$receipt]);}if($order){$pdo->prepare("DELETE FROM tbl_document_status_history WHERE document_type='order' AND document_id=?")->execute([$order]);$pdo->prepare('DELETE FROM tbl_order_detail WHERE order_id=?')->execute([$order]);$pdo->prepare('DELETE FROM tbl_order WHERE id=?')->execute([$order]);}if($product){$pdo->prepare('DELETE FROM tbl_product_lot WHERE product_id=?')->execute([$product]);$pdo->prepare('DELETE FROM tbl_warehouse_stock WHERE product_id=?')->execute([$product]);$pdo->prepare('DELETE FROM tbl_product WHERE id=?')->execute([$product]);}if($provider)$pdo->prepare('DELETE FROM tbl_provider WHERE id=?')->execute([$provider]);$pdo->commit();
}exit($failed?1:0);
